def semver_sort(versions):
    def parse_version(version):
        # Split off build metadata (after '+')
        if '+' in version:
            version_part, _ = version.split('+', 1)
        else:
            version_part = version

        # Split off pre-release (after '-')
        if '-' in version_part:
            base, prerelease = version_part.split('-', 1)
        else:
            base = version_part
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = base.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease:
            for identifier in prerelease.split('.'):
                if identifier.isdigit():
                    prerelease_identifiers.append((0, int(identifier)))
                else:
                    prerelease_identifiers.append((1, identifier))

        return (major, minor, patch, prerelease is None, prerelease_identifiers)

    def compare_key(version):
        major, minor, patch, no_prerelease, prerelease_identifiers = parse_version(version)
        # Return tuple for sorting:
        # - (major, minor, patch) for numeric comparison
        # - no_prerelease: True (no pre-release) sorts after False (has pre-release)
        #   so we negate it: versions with pre-release come first
        # - prerelease_identifiers for pre-release comparison
        return (major, minor, patch, not no_prerelease, prerelease_identifiers)

    # Stable sort to preserve input order for equal precedence
    return sorted(versions, key=compare_key)

